void __fastcall CempLockTrackerClearForThread(DWORD dwTlsIndex)
{
  if ( dwTlsIndex != -1 )
  {
    if ( *(_QWORD *)TlsGetValue(dwTlsIndex) )
      NT_ASSERT("CurrentTracker->Bitmap == 0");
    TlsSetValue(dwTlsIndex, 0LL);
  }
}
